const html: Record<string, string> = {"pill":"<a class=\"gx gx-pill\" href=\"/request-demo\"><i class=\"gx-live\" aria-hidden=\"true\"></i> Early access open · pilots now →</a>","top":"<section class=\"gx gx-marquee\" aria-label=\"Built for\"><p class=\"gx-eyebrow\">Built for the people who get the fit right</p><div class=\"gx-marquee-mask\"><ul class=\"gx-track\"><li>Fashion brands</li><li>Technical designers</li><li>Fit technicians</li><li>E-commerce managers</li><li>Online retailers</li><li>Marketplaces</li><li>Merchandisers</li><li>Customer care</li><li>Womenswear</li><li>Menswear</li><li>Activewear</li><li>Kidswear</li><li aria-hidden=\"true\">Fashion brands</li><li aria-hidden=\"true\">Technical designers</li><li aria-hidden=\"true\">Fit technicians</li><li aria-hidden=\"true\">E-commerce managers</li><li aria-hidden=\"true\">Online retailers</li><li aria-hidden=\"true\">Marketplaces</li><li aria-hidden=\"true\">Merchandisers</li><li aria-hidden=\"true\">Customer care</li><li aria-hidden=\"true\">Womenswear</li><li aria-hidden=\"true\">Menswear</li><li aria-hidden=\"true\">Activewear</li><li aria-hidden=\"true\">Kidswear</li></ul></div></section>\n<section id=\"problem\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">The problem</p><h2 class=\"gx-h2\">A quarter of online clothing comes back — and fit is the main reason.</h2><p class=\"gx-intro\">Size charts drift between styles and factories, recommendation widgets guess from body questionnaires, and return reasons sit in a spreadsheet nobody reads. The same fit problem ships again next season.</p></div><div class=\"gx-grid gx-g3\"><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"24.4\" data-dec=\"1\">24.4</b><span>%</span></div><figcaption><p>average online apparel return rate reported by US apparel decision-makers.</p><a class=\"gx-src\" href=\"https://coresight.com/research/the-true-cost-of-apparel-returns/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Coresight Research, The True Cost of Apparel Returns ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-stat-v\"><b class=\"gx-b\" data-count=\"53\" data-dec=\"0\">53</b><span>%</span></div><figcaption><p>of respondents named size and fit as the top reason apparel is returned — far ahead of colour or damage.</p><a class=\"gx-src\" href=\"https://coresight.com/research/the-true-cost-of-apparel-returns/\" target=\"_blank\" rel=\"noopener noreferrer\">Source: Coresight Research, The True Cost of Apparel Returns ↗</a></figcaption></figure><figure class=\"gx-card gx-fig gx-reveal gx-lift gx-spot gx-d4\"><div class=\"gx-stat-v\"><small>$</small><b class=\"gx-b\" data-count=\"890\" data-dec=\"0\">890</b><span>B</span></div><figcaption><p>of merchandise US retailers expected to be returned in 2024 — 16.9% of annual sales.</p><a class=\"gx-src\" href=\"https://nrf.com/media-center/press-releases/nrf-and-happy-returns-report-2024-retail-returns-total-890-billion\" target=\"_blank\" rel=\"noopener noreferrer\">Source: NRF &amp; Happy Returns, 2024 Consumer Returns in the Retail Industry ↗</a></figcaption></figure></div><p class=\"gx-small\">Published figures from third-party sources, linked above. They describe the returns problem, not SizeMemo results.</p></div></section>\n<section id=\"solution\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">What we solve</p><h2 class=\"gx-h2\">From guessed sizes to recommendations built on real garment measurements.</h2></div><div class=\"gx-grid gx-g2\"><div class=\"gx-card gx-reveal\"><p class=\"gx-eyebrow gx-eyebrow-muted\">Today</p><ul class=\"gx-list\"><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Size charts are copied between styles and quietly drift.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Recommendations come from body questionnaires, not garments.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Return reasons sit in a spreadsheet nobody reads.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">The style that runs small ships again next season.</span></li><li><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span class=\"gx-muted\">Nobody can say why a size was recommended.</span></li></ul></div><div class=\"gx-card gx-with gx-reveal gx-spot gx-d2\"><p class=\"gx-eyebrow\">With SizeMemo</p><ul class=\"gx-list\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Every style’s measurements stored and compared with your block.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Size recommendations from real garment measurements.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Return feedback analysed for fit signals per style and size.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Styles that don’t fit like the rest of the range flagged early.</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Every recommendation explains which measurements drove it.</span></li></ul></div></div></div></section>","mid":"<section id=\"compare\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Why SizeMemo</p><h2 class=\"gx-h2\">How it compares with the way fit is managed today</h2><p class=\"gx-intro\">SizeMemo works alongside your PLM and e-commerce platform — it makes fit decisions from measurements, not guesses.</p></div><div class=\"gx-table-wrap gx-reveal\"><table class=\"gx-table\"><thead><tr><th><span class=\"gx-sr\">Capability</span></th><th>Static size charts</th><th>Questionnaire widgets</th><th>PLM spec sheets</th><th class=\"gx-us\">SizeMemo</th></tr></thead><tbody><tr><th scope=\"row\">Recommends from garment measurements</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Body estimates</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Per style and size</span></td></tr><tr><th scope=\"row\">Catches styles that fit differently</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> If someone checks</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Consistency monitoring</span></td></tr><tr><th scope=\"row\">Learns from return feedback</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Black box</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Fit signals, explained</span></td></tr><tr><th scope=\"row\">Explains every recommendation</th><td><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> It’s a table</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Measurements shown</span></td></tr><tr><th scope=\"row\">Works across your whole range</th><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> One chart per brand</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Varies</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Specs only</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span> Range-wide</span></td></tr><tr><th scope=\"row\">Collects body photos or scans</th><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic part\" aria-label=\"Partly\">–</span> Some do</span></td><td><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> —</span></td><td class=\"gx-us\"><span class=\"gx-cell\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span> By design — not needed</span></td></tr></tbody></table></div></div></section>\n<section id=\"ai\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap gx-split gx-even\"><div><div><p class=\"gx-eyebrow\">AI, used carefully</p><h2 class=\"gx-h2\">Fit insight from your data — with the measurements shown.</h2><p class=\"gx-intro\">SizeMemo’s assistant reads return comments and measurement data to explain fit issues. Recommendations come from measurements; AI only explains them.</p></div><ul class=\"gx-list\"><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d0\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Summarise fit complaints for a style</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d1\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Compare a style’s measurements with your block</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d2\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>Explain why a size was recommended</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d3\"><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span>List the records behind every answer</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d4\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Guess a size without measurement data</span></li><li class=\"gx-card gx-li-card gx-reveal gx-lift gx-d5\"><span class=\"gx-ic no\" aria-label=\"No\">✕</span><span>Make claims about a customer’s body</span></li></ul></div><div class=\"gx-card gx-chat gx-reveal gx-d2\"><div class=\"gx-chat-head\">Fit assistant <span class=\"gx-badge\">Sample data</span></div><p class=\"gx-bubble-q\">Why is the Alder wrap dress being returned?</p><div class=\"gx-bubble-a\">41% of its returns mention “tight across the bust”. Its size M bust measures 2.1 cm below your block — larger than any other dress this season. Recommendation: review the spec with the factory.<em>From 64 return comments and the Alder spec sheet</em></div><p class=\"gx-bubble-q\">What size is this customer really?</p><div class=\"gx-bubble-a gx-muted\">I don’t make claims about customers’ bodies. I can recommend a size from the garment’s measurements and the fit preferences they’ve shared.</div><a class=\"gx-btn gx-mt\" href=\"/fit-demo\">Try it in the live demo →</a></div></div></section>","team":"<section id=\"team\" class=\"gx gx-section gx-tint\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Team</p><h2 class=\"gx-h2\">The people building SizeMemo</h2><p class=\"gx-intro\">Founded by Moses Marvin (Founder/CEO) and Jude Zamani (Co-founder/CTO), and built together with the teams who will use it.</p></div><div class=\"gx-mt44\"><div class=\"gx gx-grid gx-g2 gx-mt0\"><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d0\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>MM</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Founder/CEO</p><h3>Moses Marvin</h3><p>Moses founded SizeMemo so brands can recommend sizes from real measurements and stop shipping the same fit problem twice — and leads product, brands and every pilot.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Product</li><li>Brands</li><li>Pilots</li></ul></div></div></article><article class=\"gx-card gx-reveal gx-lift gx-spot gx-d2\"><div class=\"gx-person\"><div class=\"gx-avatar\" aria-hidden=\"true\"><b>JZ</b></div><div class=\"gx-min0\"><p class=\"gx-role\">Co-founder/CTO</p><h3>Jude Zamani</h3><p>Jude co-founded SizeMemo and leads its technology — from the measurement model and return analysis to the cloud platform behind it.</p><ul class=\"gx-tags\" aria-label=\"Focus areas\"><li>Fit model</li><li>Return analysis</li><li>Cloud platform</li></ul></div></div></article></div></div></div></section>\n<section id=\"roadmap\" class=\"gx gx-section\"><div class=\"gx-wrap\"><div><p class=\"gx-eyebrow\">Roadmap</p><h2 class=\"gx-h2\">Where SizeMemo is going</h2><p class=\"gx-intro\">Built with early-access customers. The order below is our plan and may change based on what pilots teach us.</p></div><ol class=\"gx-grid gx-g4 gx-ol\"><li class=\"gx-card gx-reveal gx-lift gx-now gx-d0\"><div class=\"gx-stage\"><span><i class=\"gx-live\" aria-hidden=\"true\"></i>Now</span></div><h3>Fit demo &amp; early access</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Fit demo on a fictional label</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Measurement-based recommendations</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Return feedback analysis</span></li><li><span class=\"gx-ic ok\" aria-label=\"Yes\">✓</span><span class=\"gx-muted\">Demo requests open</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d2\"><div class=\"gx-stage\"><span>Next</span></div><h3>Pilot with one brand</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Import your size charts and specs</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Return-reason import</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Fit summaries with Amazon Bedrock</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d3\"><div class=\"gx-stage\"><span>Then</span></div><h3>General availability</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">E-commerce widget</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">PLM integrations</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">SSO with roles enforced on the server</span></li></ul></li><li class=\"gx-card gx-reveal gx-lift gx-d5\"><div class=\"gx-stage\"><span>Later</span></div><h3>Exploring with pilots</h3><ul class=\"gx-list gx-list-sm\"><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Factory consistency scorecards</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Marketplace listings</span></li><li><span class=\"gx-ic part\" aria-label=\"Partly\">–</span><span class=\"gx-muted\">Grading-rule checks</span></li></ul></li></ol></div></section>\n<section id=\"faq\" class=\"gx gx-section\"><div class=\"gx-wrap gx-split\"><div><div><p class=\"gx-eyebrow\">FAQ</p><h2 class=\"gx-h2\">Questions brands ask</h2></div><a class=\"gx-link\" href=\"mailto:hello@sizememo.site\">✉ Email the founders</a></div><div class=\"gx-faq gx-reveal\"><details><summary>Does SizeMemo need body scans or photos?</summary><p>No. Recommendations come from garment measurements and the fit preferences shoppers choose to share. We don’t collect body photos or scans.</p></details><details><summary>What problem does it actually solve?</summary><p>Fit is the top reason apparel is returned, yet charts drift and return reasons go unread. SizeMemo connects measurements, charts and returns so recommendations and fit fixes come from real numbers.</p></details><details><summary>What data do we need?</summary><p>Size charts and garment measurement specs, plus return reasons if you have them. The pilot covers import from your existing files.</p></details><details><summary>How is AI used?</summary><p>To read return comments and explain fit issues — always citing the records it used. Size recommendations themselves are calculated from measurements.</p></details><details><summary>How much does it cost?</summary><p>See the pricing page. Prices are illustrative and exclude taxes.</p></details><details><summary>Is it available today?</summary><p>SizeMemo is in early access. The fit demo runs on a fictional label; a pilot runs on your range. Request a demo and a founder will reply personally.</p></details></div></div></section>","privacy":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Privacy notice</h1><h2>What this website is</h2><p>This website describes SizeMemo and includes an interactive demo that runs on sample data. No customer systems are connected.</p><h2>Demo data</h2><p>Changes you make in the demo are kept in your browser (local storage) or in the demo server’s memory and contain only sample data. Clearing site data removes them.</p><h2>Early-access requests</h2><p>When the request form is connected to a customer-relationship service (proposed: HubSpot), submitting it sends the fields you enter, your consent choices and the page address to that service so SizeMemo can reply. Product updates are sent only if you opt in. Until then, requests are kept in your browser and you are offered a pre-filled email to hello@sizememo.site.</p><h2>Analytics and cookies</h2><p>This website includes no advertising trackers. A hosting provider may process routine request data to serve and protect the site.</p><h2>Your requests</h2><p>Contact hello@sizememo.site with questions about information you have sent to SizeMemo, or to ask for it to be corrected or deleted.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@sizememo.site\">hello@sizememo.site</a></p></div></section>","terms":"<section class=\"gx gx-section gx-legal\"><div class=\"gx-wrap\"><p class=\"gx-eyebrow\">Review draft · operator details to be confirmed</p><h1 class=\"gx-h2\">Terms of use</h1><h2>Demonstration only</h2><p>The demo runs on sample data. It is not a production system and must not be used for real merchandising.</p><h2>People decide</h2><p>SizeMemo organises information and flags items for review. Decisions stay with qualified people on your team.</p><h2>Pricing and availability</h2><p>Prices shown are illustrative and exclude taxes. Early-access requests do not create a subscription or any commitment.</p><h2>Use of the site</h2><p>Use the site and demo lawfully. Do not upload personal or confidential information to the demo.</p><h2>Changes</h2><p>These terms are a review draft. Operator details, governing law and service terms will be set out before launch.</p><p class=\"gx-small gx-mt34\">Contact: <a href=\"mailto:hello@sizememo.site\">hello@sizememo.site</a></p></div></section>"};

